def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find full uniform separator rows or columns.
    row_seps = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_seps = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    out = [row[:] for row in grid]

    if row_seps:
        # Repeating horizontal bands, with the separator rows left intact.
        bounds = [-1] + row_seps + [h]
        bands = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
        period = min(b - a for a, b in bands)
        motifs = {}
        for a, b in bands:
            for r in range(a, b):
                for c in range(w):
                    if grid[r][c] != bg:
                        motifs[(r - a, c)] = grid[r][c]
        for a, b in bands:
            for (dr, c), value in motifs.items():
                if a + dr < b:
                    out[a + dr][c] = value

    elif col_seps:
        # Repeating vertical bands, with the separator columns left intact.
        bounds = [-1] + col_seps + [w]
        bands = [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]
        motifs = {}
        for a, b in bands:
            for r in range(h):
                for c in range(a, b):
                    if grid[r][c] != bg:
                        motifs[(r, c - a)] = grid[r][c]
        for a, b in bands:
            for (r, dc), value in motifs.items():
                if a + dc < b:
                    out[r][a + dc] = value

    return out
